import curses
import json
import sys
from pathlib import Path

env_file, state_file = map(Path, sys.argv[1:3])
if not env_file.is_file():
    sys.exit("Resterm: no environment file found")
try:
    data = json.loads(env_file.read_text(encoding="utf-8"))
except (OSError, ValueError) as exc:
    sys.exit(f"Resterm: cannot read environment file: {exc}")
if not isinstance(data, dict) or "$groups" in data:
    sys.exit("Resterm: expected flat named environments (groups are not supported)")
names = [
    name for name, value in data.items()
    if isinstance(value, dict) and not name.startswith("$") and name.isprintable()
]
if not names:
    sys.exit("Resterm: no named environments found")
current = state_file.read_text(encoding="utf-8").strip() if state_file.is_file() else ""
items = ["Automatic", *names]

def choose(screen):
    curses.curs_set(0)
    screen.keypad(True)
    index = names.index(current) + 1 if current in names else 0
    while True:
        screen.erase()
        height, width = screen.getmaxyx()
        if height > 0 and width > 1:
            screen.addnstr(0, 0, "Environment", width - 1, curses.A_BOLD)
            visible = max(1, height - 3)
            offset = max(0, min(index - visible // 2, len(items) - visible))
            for pos in range(offset, min(len(items), offset + visible)):
                name = items[pos]
                marker = " *" if (pos == 0 and not current) or name == current else ""
                label = f" {name}{marker}"
                if pos - offset + 1 < height:
                    screen.addnstr(pos - offset + 1, 0, label, width - 1,
                                     curses.A_REVERSE if pos == index else curses.A_NORMAL)
            if height > 2:
                screen.addnstr(height - 1, 0, "Up/Down select · Enter confirm · Esc cancel",
                               width - 1)
        screen.refresh()
        key = screen.getch()
        if key in (curses.KEY_UP, ord("k")):
            index = (index - 1) % len(items)
        elif key in (curses.KEY_DOWN, ord("j")):
            index = (index + 1) % len(items)
        elif key in (10, 13, curses.KEY_ENTER):
            return index
        elif key in (27, ord("q")):
            return None

choice = curses.wrapper(choose)
if choice is None:
    sys.exit(0)
if choice == 0:
    state_file.unlink(missing_ok=True)
else:
    state_file.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    state_file.write_text(items[choice] + "\n", encoding="utf-8")
    state_file.chmod(0o600)
print(f"Environment: {items[choice]}")
